  "help.chitMaxLoss": "ہم تجویز کرتے چھُ کہ تُہۍ کٕ آمدنی، ماہانہ واجبات، کھلے قرضوں، واجب الادا بلوں، اور بچتوں سے زیادہ سے زیادہ نقصان - ایک مقررہ فیصد نچھُ۔ جلد لینا اکثر اس سے بڑھ جاتا چھُ۔ بعد کٕ مہینوں مَنٛز عام طور پر کم لاگت آتی چھُ۔",
  "help.loanExtraTiming": "آنے والے مہینوں کو دکھاتا چھُ: جب دوسرے بل ہلکٕ ہوں تاکہ تُہۍ اس قرض پر اضافی ادائیگی کرسکٕں، اور بھاری مہینے جب تُہۍ کو کم سے کم پر قائم رہنا چاہیے۔",
  "help.incomeEntryBasis": "ٹیک ہوم ٹیکس، PF، اور مقررہ کٹوتیوں کٕ بعد تُہۍ کٕ بینک مَنٛز آنے والی چیزوں سے میل کھاتا چھُ — دباؤ اور مفت نقدی کٕ ریاضی کٕ لیے بہترین۔ مجموعی صرف اس صورت مَنٛز مفید چھُ جب تُہۍ کٕ داخل کردہ ہر نمبر قبل از ٹیکس ہو۔ اگر کُھر لے جانے کٕ آمدنی مجموعی سے کم چھُ تو مفت نقد تُہۍ کٕ اصل بینک بیلنس سے کم دکھائی دے سکتا چھُ۔",
  "help.householdPayerBillTag": "فیملی موڈ کٕ لیے اختیاری: ٹیگ کون ادا کرتا چھُ تاکہ کُھریلو نبض تقسیم ذمہ داری کو بیان کر سکٕ۔ ٹوٹل اور پریشر کٕ ریاضی ایک جیسی رہتی چھُ۔",
