  "profileHub.scoreWhy.health.what": "بل کٕ بوجھ، ادائیگی کٕ عادات، بچت بفر، اور قرض کٕ رجحان کو یکجا کرتا چھُ۔",
  "profileHub.scoreWhy.health.low": "بوجھ، بفر، یا ادائیگی کٕ مستقل مزاجی مَنٛز کمزوری اسے نیچے کھینچ رہی چھُ۔",
  "profileHub.scoreWhy.health.mid": "کچھ علاقوں مَنٛز ٹھوس - کچھ عادات یا بفر اسے اٹھا سکتے چھُ۔",
  "profileHub.scoreWhy.health.good": "مجموعی طور پر عادات اور بفر صحت مند نظر آتے چھُ۔",
  "profileHub.scoreWhy.runway.what": "مہینوں مَنٛز تُہۍ ضروریات کو پورا کر سکتے چھُ اگر آمدنی رک جائے (مائع بچت + مفت نقد)۔",
  "profileHub.scoreWhy.runway.critical": "بہت پتلی تکٕا - ایک آمدنی کٕ جھٹکٕ جذب کرنا مشکل ہوگا۔",
  "profileHub.scoreWhy.runway.thin": "آرام دہ 3-6 ماہ کٕ ریزرو کٕ نیچے۔",
  "profileHub.scoreWhy.runway.ok": "رن وے فی الحال زیادہ رٲکھو رینج مَنٛز چھُ۔",
  "profileHub.scoreWhy.flexibility.what": "مقررہ ماہانہ واجبات کٕ بعد تُہۍ کٕ پاس کتنی گنجائش چھُ۔",
  "profileHub.scoreWhy.flexibility.low": "زیادہ تر آمدنی پہلے سے ہی بار بار آنے والے بلوں کٕ لیے پرعزم چھُ۔",
  "profileHub.scoreWhy.flexibility.ok": "تُہۍ ہر ماہ بامعنی مفت نقد رقم رکھتے چھُ۔",
  "profileHub.scoreWhy.debt.what": "EMI اور قرض کٕ ادائیگی ماہانہ آمدنی کٕ حصہ کٕ طور پر۔",
  "profileHub.scoreWhy.debt.high": "EMI کٕ بوجھ بہت زیادہ چھُ — نئے قرضوں سے نقدی کٕ بہاؤ مَنٛز کمی آئے گی۔",
  "profileHub.scoreWhy.debt.ok": "قرض کٕ ادائیگی قابل انتظام بینڈ کٕ اندر ہوتی چھُ۔",
  "profileHub.scoreWhy.lending.what": "وقت پر ادائیگیوں کٕ سراغ لگاتا چھُ جو تُہۍ نے قرض مَنٛز دیا یا وصول کٕا۔",
  "profileHub.scoreWhy.lending.empty": "ابھی تک کوئی قرض دینے کٕ اندراجات نچھُ چھُ - اس اسکور کو بنانے کٕ لیے سودے اور لاگ ادائیگیوں کو شٲمِل کٔرِو۔",
  "profileHub.scoreWhy.lending.low": "دیر سے یا جزوی ادائیگیوں نے اعتماد کو کم کٕا۔",
  "profileHub.scoreWhy.lending.ok": "ادائیگی کٕ تاریخ قابل اعتماد لگتی چھُ۔",
  "profileHub.scoreFix.pressure.clearOverdue": "پہلے واجب الادا بلوں کو صاف کریں - وہ اس اسکور کو سب سے زیادہ نقصان پہنچاتے چھُ۔",
  "profileHub.scoreFix.pressure.trimSubscriptions": "سبسکرپشنز اور اختیاری EMIs کٕ جائزہ لیں جنچھُ تُہۍ روک سکتے چھُ۔",
  "profileHub.scoreFix.pressure.payOnTime": "دباؤ کو مستحکم کرنے کٕ لیے اس ماہ مقررہ تاریخوں سے پہلے ادائیگی کریں۔",
  "profileHub.scoreFix.runway.buildReserve": "ہر تنخواہ کٕ دن ایک مقررہ رقم مائع کٕ بچت مَنٛز منتقل کریں۔",
  "profileHub.scoreFix.runway.reduceBurn": "رن وے کو بڑھانے کٕ لیے غیر ضروری بار بار آنے والے بلوں کو تراشیں۔",
